package com.mavislibrary.app.ui.lounge
import org.junit.Assert.*
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.json.JSONObject
@RunWith(RobolectricTestRunner::class)
class PodcastPickerTest {
    private fun parity(id: String) {
        // Generated by JS bibleLessonPayload + plain from the bundled KJV data.
        val fixture = JSONObject(javaClass.getResource("/picker/$id.json")!!.readText())
        val raw = fixture.getJSONArray("raw")
        val expected = fixture.getJSONObject("expected")
        val actual = biblePickerDraft(fixture.getString("name"), fixture.getInt("chapter"), (0 until raw.length()).map { raw.getString(it) })
        assertEquals(expected.getString("kind"), actual.kind)
        assertEquals("Bible - ${expected.getString("chapter")}", actual.title)
        assertEquals(expected.getString("text"), actual.text)
        assertEquals(expected.getInt("originalChars"), actual.originalChars)
    }
    @Test fun johnThreeMatchesWebPayload() = parity("John")
    @Test fun psalmTwentyThreeMatchesWebPayload() = parity("Ps")
    @Test fun malformedAnnotationsAreHarmless() {
        listOf(null, "", "broken", "{}", "null", "[null,2,{},true]").forEach { assertTrue(parsePickerAnnotations(it).isEmpty()) }
    }
    @Test fun annotationsAreNewestFirstAndUnknownKindsAreIgnored() {
        val rows = parsePickerAnnotations("""[{"bookKey":"bible","kind":"note","createdAt":1},{"bookKey":"bible","kind":"wordhl","createdAt":3},{"bookKey":"bible","kind":"secret","createdAt":9}]""")
        assertEquals(listOf(3L, 1L), rows.map { it.createdAt })
    }
    @Test fun bibleGroupsAreNewestFirstAndExcludeBookmarks() {
        fun row(cfi: String, at: Long, kind: String = "note") = PickerAnnotation("bible", kind, cfi, "", "", "", at)
        val groups = groupedBibleAnnotations(listOf(row("John.3.16", 1), row("Ps.23.1", 3), row("John.3.17", 5), row("Gen.1.1", 8, "bookmark")))
        assertEquals(listOf("John.3", "Ps.23"), groups.keys.toList())
        assertEquals(listOf(5L, 1L), groups.getValue("John.3").map { it.createdAt })
    }
    @Test fun annotationLimitIsTwoThousand() {
        assertEquals(2000, parsePickerAnnotations("[" + List(2001) { """{"bookKey":"b","kind":"note"}""" }.joinToString(",") + "]").size)
    }
    @Test fun lastReadThenMarkedThenRemainingChaptersKeepBookOrder() {
        val rows = listOf(PickerChapter("One", ""), PickerChapter("Two", "", marked = true), PickerChapter("Three", "", lastRead = true), PickerChapter("Four", "", marked = true))
        assertEquals(listOf("Three", "Two", "Four", "One"), sortedPickerChapters(rows).map { it.label })
    }
    @Test fun continueReadingComesFirstEvenAtZeroPercent() {
        assertEquals(listOf("started", "first", "last"), continueReadingFirst(listOf("first", "started", "last")) { it == "started" })
    }
}
